arguments.new_string:
    return (
        f"""<!DOCTYPE html>
<html lang="{lang}">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>{title}</title>
    <style>
        body {{
            font-family: {font};
            line-height: 1.5;
            color: {color};
            background-color: {bg};
            padding: 20px;
        }}
        pre {{
            background-color: {bg};
            padding: 10px;
            border-radius: 5px;
            overflow-x: auto;
        }}
        code {{
            font-family: {font};
        }}
    </style>
</head>
<body style="background-color: {bg}; color: {color};">
{content}
</body>
</html>"""
    )

